/**
 * The full third-party notices (public/third-party-notices.txt, generated by scripts/generate-notices.mjs with every
 * production npm package and Android library and their licence texts), split into entries for the licences sheet.
 */
export interface NoticeEntry {
  /** "name version  —  licence  —  url" (or a section heading). */
  title: string;
  body: string;
  heading: boolean;
}

const RULE = /^[-=]{20,}\s*$/;
const ENTRY = /\S.*\s—\s/;

/** Entries in file order: the preamble, then a heading per section and an entry per component. */
export function parseNotices(text: string): NoticeEntry[] {
  const lines = text.replace(/\r\n?/g, '\n').split('\n');
  const out: NoticeEntry[] = [];
  let cur: NoticeEntry | null = null;
  const push = () => {
    if (cur) {
      cur.body = cur.body.replace(/^\n+|\s+$/g, '');
      out.push(cur);
    }
    cur = null;
  };
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (/^={20,}\s*$/.test(line)) {
      // ===== / heading / =====
      const next = lines[i + 1] ?? '';
      if (next.trim() && /^={20,}\s*$/.test(lines[i + 2] ?? '')) {
        push();
        out.push({ title: next.trim(), body: '', heading: true });
        i += 2;
      }
      continue;
    }
    if (ENTRY.test(line) && !line.startsWith(' ')) {
      push();
      cur = { title: line.trim(), body: '', heading: false };
      if (RULE.test(lines[i + 1] ?? '')) i += 1;
      continue;
    }
    if (!cur) cur = { title: '', body: '', heading: false };
    cur.body += `${line}\n`;
  }
  push();
  return out.filter((e) => e.heading || e.title || e.body);
}

/** Entries whose title matches every word of the query (headings stay while something under them matches). */
export function filterNotices(entries: readonly NoticeEntry[], query: string): NoticeEntry[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return [...entries];
  const hit = (e: NoticeEntry) => !e.heading && e.title !== '' && words.every((w) => e.title.toLowerCase().includes(w));
  const out: NoticeEntry[] = [];
  let heading: NoticeEntry | null = null;
  for (const e of entries) {
    if (e.heading) heading = e;
    else if (hit(e)) {
      if (heading) {
        out.push(heading);
        heading = null;
      }
      out.push(e);
    }
  }
  return out;
}

let cache: Promise<NoticeEntry[]> | null = null;

export function loadNotices(fetcher: typeof fetch = fetch, base: string = String(import.meta.env.BASE_URL ?? '/')): Promise<NoticeEntry[]> {
  if (!cache) {
    const url = `${base.endsWith('/') ? base : `${base}/`}third-party-notices.txt`;
    cache = fetcher(url)
      .then((r) => {
        if (!r.ok) throw new Error(`notices ${r.status}`);
        return r.text();
      })
      .then(parseNotices)
      .catch((e) => {
        cache = null;
        throw e;
      });
  }
  return cache;
}
